import Link from 'next/link';
import { pageMetadata } from '@/lib/seo';
import { FOUNDED_YEAR } from '@/constants/app';
import { cumulativeDeploymentsByYear } from '@/lib/map/process';
import type { JobRecord } from '@/types/JobRecord';
// Build-time snapshot of the headline numbers (regenerated by the data
// pipeline alongside the operations JSON, so it can't drift from the map's
// dataset). The map's runtime fetch is versioned with this snapshot's
// generatedAt stamp, so page copy, the live counter, the chart, and the
// map's own panel all describe the same dataset generation.
import operationsStats from '../../../../public/data/operations_stats.json';
// Build-time import (server-only — nothing here ships to the client): the
// slim operations dataset feeds the default all-systems chart curve,
// computed once at build with the exact same function the client uses for
// filtered curves. Same pipeline generation as the stats snapshot above.
import operationsData from '../../../../public/data/operations_data.json';
import TrackRecordExperience from './TrackRecordExperience';

const STATS = {
  deployments: operationsStats.deployments,
  countries: operationsStats.countries,
  years: new Date().getFullYear() - FOUNDED_YEAR,
};

export const metadata = pageMetadata({
  title: 'Track Record',
  description: `Explore Petromac's global deployment history across ${STATS.countries}+ countries with our interactive operations map.`,
  path: '/track-record',
});

// All-systems cumulative curve, baked at build via the shared calculation.
// (Double cast: the JSON's Year field is a string; JobRecord types it as
// number — cumulativeDeploymentsByYear coerces per row.)
const ALL_DATA = operationsData as unknown as JobRecord[];
const ALL_SYSTEMS = Array.from(new Set(ALL_DATA.map((job) => job.System).filter(Boolean)));
const DEFAULT_CHART = cumulativeDeploymentsByYear(ALL_DATA, ALL_SYSTEMS);

/**
 * Records & milestones. Every fact verified against repo content
 * (success-stories PDF text / publications list). No per-story deep links
 * exist in the flipbook, so cards link to the flipbook (or publications
 * for the SPE paper).
 */
const RECORDS = [
  {
    headline: '80°',
    title: 'World-record gravity descent',
    context:
      'Free descent to 80° deviation in open hole — no tractoring, no pipe. The published record run reached near-horizontal.',
    href: '/success-stories/flipbook',
    cta: 'Success stories',
  },
  {
    headline: '72° in 6" hole',
    title: 'Record slim-hole deviation — Kuwait',
    context:
      'Slim tool taxis carried a triple combo plus pressure testing to a record 72° in a 6" wellbore — no pipe-conveyed logging.',
    href: '/success-stories/flipbook',
    cta: 'Success stories',
  },
  {
    headline: '8 days saved',
    title: 'Pipe-conveyed logging eliminated — Mexico',
    context:
      'Gravity descent with Wireline Express replaced PCL on a deviated well, saving 8 days of rig time.',
    href: '/success-stories/flipbook',
    cta: 'Success stories',
  },
  {
    headline: '$9.4M saved',
    title: 'Deepwater high-angle well — Nam Con Son Basin',
    context: 'Innovative conveyance on a deepwater, high-angle well — published at SPE/ICoTA 2017.',
    href: '/about/publications',
    cta: 'Read the paper',
  },
];

/**
 * The map IS the page: no header band — the map card (with its own header
 * row: H1, filter chips, live counter) opens the page and dominates the
 * first viewport, with the filter-aware growth chart directly beneath it,
 * then the verified records strip and the Success Stories CTA.
 */
export default function TrackRecordPage() {
  return (
    <div className="bg-slate-50">
      {/* Map hero — card + chart share the dark frame. */}
      <section className="bg-slate-900 pt-4 md:pt-5 pb-8 md:pb-10">
        <div className="px-3 md:px-6 lg:px-10">
          <TrackRecordExperience
            stats={STATS}
            dataVersion={operationsStats.generatedAt}
            defaultChart={DEFAULT_CHART}
          />
        </div>
      </section>

      {/* Records & milestones — verified facts, server-rendered. The card
          header's "Records & success stories ↓" link lands here (smooth
          scroll + scroll-margin come from globals.css). */}
      <section id="records" className="container mx-auto px-4 py-10 md:py-14">
        <h2 className="font-heading text-2xl md:text-3xl font-bold text-slate-900 mb-6">
          Records &amp; milestones
        </h2>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 md:gap-5">
          {RECORDS.map((record) => (
            <Link
              key={record.title}
              href={record.href}
              className="group flex flex-col rounded-xl bg-white ring-1 ring-slate-200 shadow-card p-5 hover:ring-brand/40 hover:shadow-lg transition-all"
            >
              <p className="font-heading text-3xl font-bold text-brand tabular-nums">
                {record.headline}
              </p>
              <p className="mt-1.5 font-semibold text-slate-900 text-sm">{record.title}</p>
              <p className="mt-2 text-sm text-slate-600 leading-relaxed flex-1">{record.context}</p>
              <p className="mt-3 text-sm font-semibold text-brand">
                {record.cta}{' '}
                <span
                  aria-hidden="true"
                  className="inline-block transition-transform group-hover:translate-x-0.5"
                >
                  →
                </span>
              </p>
            </Link>
          ))}
        </div>

        <div className="mt-8 flex justify-center">
          <Link
            href="/success-stories/flipbook"
            className="
              inline-flex items-center gap-2 whitespace-nowrap
              px-7 py-3 rounded-full font-semibold text-white
              bg-brand hover:bg-brand/90 shadow-lg shadow-blue-900/20
              ring-1 ring-blue-900/10
              transition-all hover:translate-y-[-1px] hover:shadow-xl
              focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2
            "
          >
            <span>Read the Success Stories</span>
            <svg
              className="w-4 h-4"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
              aria-hidden="true"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2.5}
                d="M9 5l7 7-7 7"
              />
            </svg>
          </Link>
        </div>
      </section>
    </div>
  );
}
